      "description": "Pillar 1 / Stream A — return a hierarchical tree of namespaces with memory counts. Walks the `/`-delimited namespace paths grouped from live memories (expired rows excluded). Each node carries `count` (memories at exactly that namespace) and `subtree_count` (count plus all descendants visible within `depth`); the response also exposes `total_count` for the prefix and a `truncated` flag set when `limit` forced rows to be dropped from the tree.",
      "inputSchema": {
        "properties": {
          "depth": {
            "default": 8,
            "description": "Max levels to descend below the prefix. Memories deeper than this still contribute to `subtree_count` of the boundary ancestor.",
            "maximum": 8,
            "minimum": 0,
            "type": "integer"
          },
          "limit": {
            "default": 1000,
            "description": "Cap on `(namespace, count)` rows walked when assembling the tree. Densest namespaces win when truncated.",
            "maximum": 10000,
            "minimum": 1,
            "type": "integer"
          },
          "namespace_prefix": {
            "description": "Restrict the tree to memories at this namespace OR any descendant. Omit to walk the full tree. Trailing '/' is tolerated.",
            "type": "string"
          }
        },
        "type": "object"
      },
      "name": "memory_get_taxonomy"
    },
